=== app/ReservationService.java
     1	package br.com.marealta.app;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.domain.ErrorCode;
     5	import br.com.marealta.domain.Receipt;
     6	import br.com.marealta.domain.Reservation;
     7	import br.com.marealta.domain.ReservationStatus;
     8	import br.com.marealta.domain.Room;
     9	import br.com.marealta.domain.RoomCatalog;
    10	import br.com.marealta.notification.Notifier;
    11	import br.com.marealta.notification.ReservationEvent;
    12	
    13	import java.util.function.UnaryOperator;
    14	
    15	public class ReservationService {
    16	    private final RoomCatalog rooms;
    17	    private final ReservationRepository reservations;
    18	    private final Notifier notifier;
    19	
    20	    public ReservationService(RoomCatalog rooms, ReservationRepository reservations, Notifier notifier) {
    21	        this.rooms = rooms;
    22	        this.reservations = reservations;
    23	        this.notifier = notifier;
    24	    }
    25	
    26	    public synchronized Reservation create(CreateReservation cmd) {
    27	        Room room = rooms.require(cmd.roomNumber());
    28	        if (cmd.guests() > room.capacity()) {
    29	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    30	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    31	        }
    32	        if (reservations.existsActiveOverlap(room.number(), cmd.checkIn(), cmd.checkOut())) {
    33	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    34	                    "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    35	        }
    36	        return reservations.insert(Reservation.pending(room, cmd.guestName(), cmd.guestEmail(), cmd.guestCpf(),
    37	                cmd.checkIn(), cmd.checkOut(), cmd.guests(), cmd.ratePlan()));
    38	    }
    39	
    40	    public Reservation get(long id) {
    41	        return reservations.find(id).orElseThrow(() ->
    42	                new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe"));
    43	    }
    44	
    45	    public synchronized Reservation confirm(long id) {
    46	        Reservation confirmed = transition(id, Reservation::confirmed);
    47	        notifier.publish(new ReservationEvent.Confirmed(confirmed));
    48	        return confirmed;
    49	    }
    50	
    51	    public synchronized Reservation cancel(long id) {
    52	        boolean wasConfirmed = get(id).status() == ReservationStatus.CONFIRMED;
    53	        Reservation cancelled = transition(id, Reservation::cancelled);
    54	        if (wasConfirmed) {
    55	            notifier.publish(new ReservationEvent.Cancelled(cancelled));
    56	        }
    57	        return cancelled;
    58	    }
    59	
    60	    public synchronized Reservation checkIn(long id) {
    61	        return transition(id, Reservation::checkedIn);
    62	    }
    63	
    64	    public synchronized Receipt checkOut(long id) {
    65	        return receiptOf(transition(id, Reservation::checkedOut));
    66	    }
    67	
    68	    /** Segunda via: só existe para reserva paga. */
    69	    public Receipt document(long id) {
    70	        Reservation reservation = get(id);
    71	        if (!reservation.wasPaid()) {
    72	            throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
    73	                    "Só existe comprovante para reserva paga; esta está " + reservation.status());
    74	        }
    75	        return receiptOf(reservation);
    76	    }
    77	
    78	    private Receipt receiptOf(Reservation reservation) {
    79	        return Receipt.of(reservation, rooms.require(reservation.roomNumber()));
    80	    }
    81	
    82	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
    83	        Reservation changed = change.apply(get(id));
    84	        reservations.update(changed);
    85	        return changed;
    86	    }
    87	}
