     9	/** O financeiro vê os pagamentos que entram e os reembolsos a devolver. */
    10	public class FinanceSubscriber implements Subscriber {
    11	    static final String ADDRESS = "financeiro@pousadamarealta.com.br";
    12	
    13	    @Override
    14	    public List<Notification> onConfirmed(ReservationEvent.Confirmed event) {
    15	        Reservation r = event.reservation();
    16	        String body = "Pagamento recebido da reserva nº " + r.id() + " (quarto " + r.roomNumber() + ").\n"
    17	                + "Valor pago: " + Formats.money(r.amountPaid());
    18	        return List.of(Notification.email(ADDRESS, "Pagamento recebido - reserva " + r.id(), body));
    19	    }
    20	
    21	    @Override
    22	    public List<Notification> onCancelled(ReservationEvent.Cancelled event) {
    23	        Reservation r = event.reservation();
    24	        if (r.refund().signum() == 0) {
    25	            return List.of();
    26	        }
    27	        String body = "A reserva nº " + r.id() + " (quarto " + r.roomNumber() + ") foi cancelada.\n"
    28	                + "Valor a devolver: " + Formats.money(r.refund());
    29	        return List.of(Notification.email(ADDRESS, "Reembolso - reserva " + r.id(), body));
    30	    }
    31	}
