=== notification/Notifier.java
     1	package br.com.marealta.notification;
     2	
     3	import br.com.marealta.app.MessageRepository;
     4	import br.com.marealta.app.Notification;
     5	
     6	import java.util.List;
     7	
     8	/** Entrega cada evento a todos os interessados e guarda o que eles mandam. */
     9	public class Notifier {
    10	    private final List<Subscriber> subscribers;
    11	    private final MessageRepository sent;
    12	
    13	    public Notifier(List<Subscriber> subscribers, MessageRepository sent) {
    14	        this.subscribers = List.copyOf(subscribers);
    15	        this.sent = sent;
    16	    }
    17	
    18	    public void publish(ReservationEvent event) {
    19	        for (Subscriber subscriber : subscribers) {
    20	            for (Notification notification : react(subscriber, event)) {
    21	                sent.save(notification);
    22	            }
    23	        }
    24	    }
    25	
    26	    private static List<Notification> react(Subscriber subscriber, ReservationEvent event) {
    27	        return switch (event) {
    28	            case ReservationEvent.Confirmed e -> subscriber.onConfirmed(e);
    29	            case ReservationEvent.Cancelled e -> subscriber.onCancelled(e);
    30	        };
    31	    }
    32	}
