     5	import java.util.List;
     6	
     7	/**
     8	 * Quem quer ser avisado. Cada interessado (hóspede, governança, financeiro, restaurante, transfer...) é uma
     9	 * implementação própria; para incluir ou tirar um, basta mexer na lista em {@code Main}. Cada método cobre um
    10	 * tipo de evento e, por padrão, não avisa ninguém.
    11	 */
    12	public interface Subscriber {
    13	    default List<Notification> onConfirmed(ReservationEvent.Confirmed event) {
    14	        return List.of();
    15	    }
    16	
