    10	import com.fasterxml.jackson.databind.DeserializationFeature;
    11	import com.fasterxml.jackson.databind.ObjectMapper;
    12	import com.fasterxml.jackson.databind.SerializationFeature;
    13	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    14	import io.javalin.Javalin;
    15	import io.javalin.http.Context;
    16	import io.javalin.json.JavalinJackson;
    17	import org.slf4j.Logger;
    18	import org.slf4j.LoggerFactory;
    19	
    20	import java.time.LocalDate;
    21	import java.time.YearMonth;
    22	import java.time.format.DateTimeParseException;
    23	import java.util.Map;
    24	import java.util.function.Function;
    25	
    26	public class WebApp {
    27	    private static final Logger log = LoggerFactory.getLogger(WebApp.class);
    28	    private static final String CSV = "text/csv; charset=utf-8";
    29	
    30	    private final RoomCatalog rooms;
    31	    private final ReservationService service;
    32	    private final MessageRepository messages;
    33	    private final OccupancyReport occupancy;
    34	    private final RevenueReport revenue;
    35	    private final ObjectMapper mapper = new ObjectMapper()
    36	            .registerModule(new JavaTimeModule())
    37	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    38	            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
    39	    private final ReservationRequestParser parser = new ReservationRequestParser(mapper);
    40	
    41	    public WebApp(RoomCatalog rooms, ReservationService service, MessageRepository messages,
    42	                  OccupancyReport occupancy, RevenueReport revenue) {
    43	        this.rooms = rooms;
    44	        this.service = service;
    45	        this.messages = messages;
    46	        this.occupancy = occupancy;
    47	        this.revenue = revenue;
    48	    }
    49	
    50	    public Javalin create() {
    51	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    52	
    53	        app.get("/rooms", ctx -> ctx.json(rooms.all().stream().map(RoomView::of).toList()));
    54	
    55	        app.post("/reservations", ctx -> ctx.status(201).json(service.create(parser.parse(ctx.body()))));
    56	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(id(ctx))));
    57	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(id(ctx))));
    58	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(id(ctx))));
    59	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(id(ctx))));
    60	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
    61	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
    62	
    63	        app.get("/messages", ctx -> ctx.json(messages.findAll()));
    64	
    65	        app.get("/reports/occupancy", ctx -> csv(ctx, "date", LocalDate::parse, occupancy::generate));
    66	        app.get("/reports/revenue", ctx -> csv(ctx, "month", YearMonth::parse, revenue::generate));
    67	
    68	        app.exception(DomainException.class, (e, ctx) ->
    69	                ctx.status(e.code().httpStatus()).json(Map.of("error", e.code().name(), "message", e.getMessage())));
    70	        app.exception(Exception.class, (e, ctx) -> {
    71	            log.error("Erro inesperado", e);
    72	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    73	        });
    74	        return app;
    75	    }
    76	
    77	    private static long id(Context ctx) {
    78	        try {
    79	            return Long.parseLong(ctx.pathParam("id"));
    80	        } catch (NumberFormatException e) {
    81	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe");
    82	        }
    83	    }
    84	
    85	    private static <T> void csv(Context ctx, String param, Function<String, T> parse, Function<T, String> report) {
    86	        String raw = ctx.queryParam(param);
    87	        if (raw == null) {
    88	            throw ReservationRequestParser.invalid("Parâmetro " + param + " é obrigatório");
    89	        }
    90	        T value;
    91	        try {
    92	            value = parse.apply(raw);
    93	        } catch (DateTimeParseException e) {
    94	            throw ReservationRequestParser.invalid("Parâmetro " + param + " em formato inválido");
    95	        }
    96	        ctx.contentType(CSV).result(report.apply(value));
    97	    }
    98	}
