    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Lê e valida o corpo do POST /reservations; qualquer problema é INVALID_REQUEST. */
    14	final class ReservationRequestParser {
    15	    private final ObjectMapper mapper;
    16	
    17	    ReservationRequestParser(ObjectMapper mapper) {
    18	        this.mapper = mapper;
    19	    }
    20	
    21	    CreateReservation parse(String body) {
    22	        JsonNode json;
    23	        try {
    24	            json = mapper.readTree(body);
    25	        } catch (Exception e) {
    26	            throw invalid("O corpo não é um JSON válido");
    27	        }
    28	        if (json == null || !json.isObject()) {
    29	            throw invalid("O corpo deve ser um objeto JSON");
    30	        }
    31	        LocalDate checkIn = date(json, "checkIn");
    32	        LocalDate checkOut = date(json, "checkOut");
    33	        int guests = integer(json, "guests");
    34	        if (!checkOut.isAfter(checkIn)) {
    35	            throw invalid("A saída deve ser depois da entrada");
    36	        }
    37	        if (guests < 1) {
    38	            throw invalid("É preciso pelo menos um hóspede");
    39	        }
    40	        String email = text(json, "guestEmail");
    41	        if (!email.contains("@")) {
    42	            throw invalid("guestEmail inválido");
    43	        }
    44	        return new CreateReservation(integer(json, "roomNumber"), text(json, "guestName"), email,
    45	                text(json, "guestCpf"), checkIn, checkOut, guests, ratePlan(json));
    46	    }
    47	
    48	    private static String text(JsonNode json, String field) {
    49	        JsonNode node = json.get(field);
    50	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    51	            throw invalid("Campo " + field + " ausente ou inválido");
    52	        }
    53	        return node.asText().trim();
    54	    }
    55	
    56	    private static int integer(JsonNode json, String field) {
    57	        JsonNode node = json.get(field);
    58	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    59	            throw invalid("Campo " + field + " ausente ou inválido");
    60	        }
    61	        return node.asInt();
    62	    }
    63	
    64	    private static LocalDate date(JsonNode json, String field) {
    65	        try {
    66	            return LocalDate.parse(text(json, field));
    67	        } catch (DateTimeParseException e) {
    68	            throw invalid("Campo " + field + " deve ter o formato AAAA-MM-DD");
    69	        }
    70	    }
    71	
    72	    private static RatePlan ratePlan(JsonNode json) {
    73	        try {
    74	            return RatePlan.valueOf(text(json, "ratePlan"));
    75	        } catch (IllegalArgumentException e) {
    76	            throw invalid("Campo ratePlan inválido");
    77	        }
    78	    }
    79	
    80	    static DomainException invalid(String message) {
    81	        return new DomainException(ErrorCode.INVALID_REQUEST, message);
    82	    }
    83	}
