     8	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
     9	        BigDecimal subtotal = Money.ZERO;
    10	        int nights = 0;
    11	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    12	            subtotal = subtotal.add(Season.nightPrice(room, night));
    13	            nights++;
    14	        }
    15	        BigDecimal discount = plan.discountOn(subtotal);
    16	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
