    25	
    26	    public static Reservation pending(Room room, String guestName, String guestEmail, String guestCpf,
    27	                                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan) {
    28	        Quote quote = Quote.of(room, checkIn, checkOut, plan);
    29	        return new Reservation(null, room.number(), guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    30	                plan, quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    31	                PENDING, Money.ZERO, null);
