     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	/** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
     8	public final class Season {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	
    11	    private Season() {
    12	    }
    13	
    14	    public static boolean isHigh(LocalDate night) {
    15	        Month month = night.getMonth();
    16	        return month == Month.JANUARY
    17	                || month == Month.FEBRUARY
    18	                || month == Month.JULY
    19	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    20	    }
    21	
    22	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    23	        BigDecimal rate = room.nightlyRate();
    24	        return isHigh(night) ? Money.round(rate.multiply(HIGH_SEASON_MULTIPLIER)) : rate;
    25	    }
    26	}

