 10	import java.time.LocalDate;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	import java.util.Optional;
 14	
 15	class InMemoryRepositories {
 16	    static class Reservations implements ReservationRepository {
 17	        private final List<Reservation> items = new ArrayList<>();
 18	
 19	        public Reservation insert(Reservation r) {
 20	            Reservation saved = r.withId(items.size() + 1);
 21	            items.add(saved);
 22	            return saved;
 23	        }
 24	
 25	        public void update(Reservation r) {
 26	            items.set((int) (r.id() - 1), r);
 27	        }
 28	
 29	        public Optional<Reservation> find(long id) {
 30	            return id >= 1 && id <= items.size() ? Optional.of(items.get((int) id - 1)) : Optional.empty();
 31	        }
 32	
 33	        public List<Reservation> findAll() {
 34	            return List.copyOf(items);
 35	        }
 36	
 37	        public boolean existsActiveOverlap(int room, LocalDate in, LocalDate out) {
 38	            return items.stream().anyMatch(r -> r.roomNumber() == room && r.status() != ReservationStatus.CANCELLED
 39	                    && r.checkIn().isBefore(out) && in.isBefore(r.checkOut()));
 40	        }
 41	    }
 42	
 43	    static class Messages implements MessageRepository {
 44	        private final List<Message> items = new ArrayList<>();
 45	
 46	        public Message save(Notification n) {
 47	            Message m = new Message(items.size() + 1, n.channel(), n.to(), n.subject(), n.body());
 48	            items.add(m);
 49	            return m;
 50	        }
 51	
 52	        public List<Message> findAll() {
 53	            return List.copyOf(items);
 54	        }
 55	    }
 56	}

